package com.cretas.aims.blueprint.draftentry;
import com.cretas.aims.entity.criticalcontroldraft.CriticalControlDraft; import com.cretas.aims.repository.criticalcontroldraft.CriticalControlDraftRepository; import com.cretas.aims.service.criticalcontroldraft.CriticalControlDraftModels; import com.cretas.aims.service.qualityreleasedraft.QualityReleaseTemplateDraftCommand; import com.cretas.aims.service.qualityreleasedraft.QualityReleaseTemplateDraftModels.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Component; import java.util.*;
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name = "cretas.platform.factory-assembly.enabled", havingValue = "true", matchIfMissing = false)
@Component public class QualityReleaseDraftProposer implements CapabilityDraftProposer { private static final String WHY="蓝图没有质量检验项目、关键控制关联、采样、严重度和放行策略的完整事实"; private static <E extends Enum<E>> List<Option> opts(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(e->new Option(e.name(),e.name())).toList();} private static <E extends Enum<E>> String ec(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(Enum::name).collect(java.util.stream.Collectors.joining("、"))+" 之一";} private static List<RequiredInput> policyFields(){return List.of(RequiredInput.integer("maximumMajorFailuresForConditionalReview","重大失败上限",WHY,"0–1000",0,1000),RequiredInput.integer("maximumMinorFailuresForConditionalReview","次要失败上限",WHY,"0–1000",0,1000),RequiredInput.oneOf("approvalRole","审批角色",WHY,ec(ResponsibleRole.class),opts(ResponsibleRole.class)),RequiredInput.integer("recordRetentionDays","保留天数",WHY,"0–3650",0,3650),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));} private static List<RequiredInput> fields(){return List.of(RequiredInput.oneOf("subjectType","对象类型",WHY,ec(SubjectType.class),opts(SubjectType.class)),RequiredInput.oneOf("subjectRefType","对象引用",WHY,ec(SubjectRefType.class),opts(SubjectRefType.class)),RequiredInput.text("subjectRefId","对象标识",WHY,"最长 128 位",128),RequiredInput.text("linkedCriticalControlItemId","关键控制项目",WHY,"最长 128 位",128),RequiredInput.text("itemCode","项目编码",WHY,"最长 64 位",64),RequiredInput.text("itemName","项目名称",WHY,"最长 200 位",200),RequiredInput.oneOf("category","类别",WHY,ec(QualityCategory.class),opts(QualityCategory.class)),RequiredInput.oneOf("valueType","值类型",WHY,ec(ValueType.class),opts(ValueType.class)),RequiredInput.text("unit","单位",WHY,"最长 32 位",32).allowNull(),RequiredInput.text("inspectionMethod","检验方法",WHY,"最长 500 位",500),RequiredInput.oneOf("samplingStrategy","采样策略",WHY,ec(SamplingStrategy.class),opts(SamplingStrategy.class)),RequiredInput.integer("minimumSampleSize","最小样本",WHY,"1–100000",1,100000),RequiredInput.oneOf("severity","严重度",WHY,ec(Severity.class),opts(Severity.class)),RequiredInput.bool("required","是否必检",WHY,"是 / 否"),RequiredInput.oneOf("responsibleRole","责任角色",WHY,ec(ResponsibleRole.class),opts(ResponsibleRole.class)),RequiredInput.integer("recordRetentionDays","保留天数",WHY,"0–3650",0,3650),RequiredInput.values("authorityCodes","法规依据",WHY,"至少 1 项","依据",1,20,RequiredInput.text("authority","依据",WHY,"最长 128 位",128)),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500));} private final CriticalControlDraftRepository controls; public QualityReleaseDraftProposer(CriticalControlDraftRepository controls){this.controls=controls;} public String capabilityId(){return QualityReleaseTemplateDraftCommand.CAPABILITY_ID;} public Proposed propose(Source s){CriticalControlDraft probe=new CriticalControlDraft();probe.setFactoryId(s.factoryId());probe.setBlueprintId(s.blueprint().getId());probe.setBlueprintVersion(s.blueprint().getVersion().longValue());probe.setSourceDigest(s.sourceDigest());probe.setStatus("DRAFT");probe.setDependencyClosureComplete(true);probe.setDependencyBasis(CriticalControlDraftModels.DEPENDENCY_BASIS);var row=controls.findAll(Example.of(probe),Sort.by(Sort.Direction.DESC,"createdAt")).stream().filter(x->x.getDesiredDigest()!=null&&x.getDesiredDigest().matches("[0-9a-f]{64}")).findFirst().orElse(null);if(row==null)return Proposed.blocked("UPSTREAM_MISSING","质量放行必须绑定同蓝图关键控制草稿","先完成关键控制草稿");var req=new DraftRequest(s.factoryId(),s.blueprint().getId(),s.blueprint().getVersion(),s.sourceDigest(),new CriticalControlPin(row.getId(),row.getDesiredDigest()),List.of(),null,null,null,0);return Proposed.single(capabilityId(),"质量放行模板",req,List.of(RequiredInput.object("releasePolicy","放行策略",WHY,"完整填写",policyFields()),RequiredInput.list("items","质量检验项目",WHY,"至少 1 条","项目",1,200,fields())),List.of(new Evidence("criticalControl",row.getId()+" / "+row.getDesiredDigest())));}}
